(* [comment removed for export] *)
Definition FIND_STACK : Z := 64 + LBL_STACK.

Definition find_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (h : Z) (S : list Z) (ns : NS) (em : gmap Z elt) (r lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ ATreeR m' h S ns em /\ ACONST m'.

Definition find_stmt : Prop := forall (h kv pc kp : Z) (pw : word) (k : list byte) (S : list Z) (ns : NS) (em : gmap Z elt)
    (fuel : nat) (r lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ATreeR m h S ns em ->
  rw_cells bsegs m kv [C8 (wz kp); C8 (wz (zlength k))] -> bytes_at bsegs m kp k -> rw_cells bsegs m pc [C8 pw] ->
  RBMem.find fuel (cmpL key_lt (key_of em) (zbytes k)) (cmpU key_lt (key_of em) (zbytes k)) ns h = Some r ->
  stk bsegs m lo (bv_unsigned sp) -> lo + FIND_STACK <= bv_unsigned sp -> aceil <= lo ->      (* [comment removed for export] *)
  (kv + 16 <= lo \/ bv_unsigned sp <= kv) -> (kp + zlength k <= lo \/ bv_unsigned sp <= kp) -> (pc + 8 <= lo \/ bv_unsigned sp <= pc) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  kv mod 8 = 0 -> accessible m kv 16 -> accessible m kp (zlength k) -> pc mod 8 = 0 -> accessible m pc 8 -> ACONST m ->
  (* [comment removed for export] *)
  0 < pc -> bv_unsigned sp mod 16 = 0 -> (0 < zlength k -> 0 < kp) ->
  evt bsegs (find_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc h S ns em r lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz h) (wz kv) (wz pc) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_RB_FIND) fc None m (seg_rom bsegs)).

