(* [comment removed for export] *)
Definition FFIND_STACK : Z := 64 + FIND_STACK.

Definition ffind_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa : Z) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (res r lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (res, res + 8)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' res [C8 (wz r)]
    /\ AFieldsC m' Fa S L ns ls em
    /\ ACONST m' /\ stack0 m' lo shi.

Definition ffind_stmt : Prop := forall (res Fa kp : Z) (k : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt)
    (fuel : nat) (r lo shi : Z) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AFieldsC m Fa S L ns ls em ->
  bytes_at bsegs m kp k -> rw_cells bsegs m res [CB 8 rj] ->
  fields_find fuel (cmpL key_lt (key_of em) (zbytes k)) (cmpU key_lt (key_of em) (zbytes k)) ns ls Fa = Some r ->
  stk bsegs m lo (bv_unsigned sp) -> lo + FFIND_STACK <= bv_unsigned sp -> aceil <= lo ->     (* [comment removed for export] *)
  (kp + zlength k <= lo \/ bv_unsigned sp <= kp) ->
  (res + 8 <= lo \/ bv_unsigned sp <= res) ->                                               (* [comment removed for export] *)
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  accessible m kp (zlength k) ->
  res mod 8 = 0 -> accessible m res 8 -> awin (res, res + 8) -> fwin Fa em (res, res + 8) ->
  (* [comment removed for export] *)
  (0 < zlength k -> 0 < kp) -> 0 < res ->
  evt bsegs (ffind_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa S L ns ls em res r lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz Fa) (wz kp) (wz (zlength k)) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELDS_FIND_SV) fc None m (seg_rom bsegs)).

